DROP TABLE IF EXISTS `ec_page`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ec_page` (
  `page_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `post_title` varchar(255) NOT NULL,
  `post_title_es` varchar(255) DEFAULT NULL,
  `post_slug` varchar(255) NOT NULL,
  `footer_section` varchar(255) DEFAULT NULL,
  `post_content` mediumtext DEFAULT NULL,
  `post_content_es` mediumtext DEFAULT NULL,
  `post_type` varchar(100) NOT NULL,
  `featured_image` varchar(255) DEFAULT NULL,
  `enabled` enum('0','1') NOT NULL DEFAULT '0',
  `created` datetime NOT NULL DEFAULT current_timestamp(),
  `modified` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`page_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
