INSERT INTO `ec_product` VALUES (1,1,1,'Small Mixture Grinder Mixer Blender',1,1,NULL,'It is a portable mill that combines the mixing and grinding operations. Grinding of ingredients generally improves feed digestibility, acceptability, mixing properties and pelletability. Grain is typically pulverized in a grinder-mixer either by hammer mills or roller mills.','attribute',NULL,'','[\"Hk1.avif\"]','[{\"id\":1,\"price\":\"80\"},{\"id\":2,\"price\":\"50\"}]','[{\"id\":2,\"price\":\"120\"},{\"id\":1,\"price\":\"80\"}]','[{\"name\":\"extra large\",\"regular_price\":\"300\",\"sales_price\":\"280\",\"images\":[\"img_68862bb88765b1753623480.png\"]},{\"name\":\"medium\",\"regular_price\":\"260\",\"sales_price\":\"220\",\"images\":[\"img_68862bb88780a1753623480.png\"]}]',988,'1','2025-07-27 19:08:00','2026-07-14 18:14:17'),(4,1,1,' stainless steel cookware set',1,1,1,'A 12-piece, premium food-grade (304/18/8) stainless steel cookware set designed for durability and even heat distribution, featuring riveted, stay-cool handles and induction-compatible bases. This set generally includes versatile, rust-resistant pots and pans with lids, such as a kadhai, fry pan, saucepan, and stockpot.','simple',NULL,'','[\"Hk2.webp\"]','[{\"id\":3,\"price\":\"0\"},{\"id\":1,\"price\":\"30\"},{\"id\":2,\"price\":\"60\"}]','[{\"id\":1,\"price\":\"29\"},{\"id\":3,\"price\":\"29\"},{\"id\":2,\"price\":\"39\"}]','[{\"name\":\"default\",\"regular_price\":\"250\",\"sales_price\":\"230\",\"images\":[\"img_68862e12d46531753624082.png\"]}]',902,'1','2025-07-27 19:18:02','2026-07-14 18:14:17'),(5,1,1,'Premium Fresh Fruit Basket',1,1,1,'A delightful mix of seasonal fruits packed together for freshness, taste, and nutrition.','simple',NULL,'','[\"Hk3.webp\"]','[{\"id\":1,\"price\":\"120\"}]','[{\"id\":1,\"price\":\"80\"},{\"id\":2,\"price\":\"190\"}]','[{\"name\":\"default\",\"regular_price\":\"320\",\"sales_price\":\"300\",\"images\":[\"img_68862f0b13bf21753624331.png\"]}]',807,'1','2025-07-27 19:22:11','2026-07-14 18:14:17'),(6,1,1,'Rice Pressure Cooker',1,1,1,'An electric rice pressure cooker is a versatile, automated kitchen appliance that combines high-pressure steam technology with precise temperature sensors to cook rice and grains in 15–25 minutes. It features a sealed, locking pot, a non-stick inner bowl, and \"keep warm\" functions to prevent overcooking.','simple',NULL,'','[\"Hk4.jpg\"]','[{\"id\":2,\"price\":\"130\"}]','[{\"id\":1,\"price\":\"90\"}]','[{\"name\":\"default\",\"regular_price\":\"188\",\"sales_price\":\"162\",\"images\":[\"img_6889da3252a041753864754.jpg\"]}]',1000,'1','2025-07-30 14:09:14','2026-07-14 18:14:17'),(7,1,2,'Modern Comfort 2-Seater Sofa',2,2,NULL,'A sleek and cozy 2-seater sofa designed to add comfort and modern style to your living space.','simple',NULL,'','[\"Hf1.avif\"]','[{\"id\":2,\"price\":\"130\"}]','[{\"id\":1,\"price\":\"90\"}]','[{\"name\":\"default\",\"regular_price\":\"188\",\"sales_price\":\"162\",\"images\":[\"img_6889da3a18fdd1753864762.jpg\"]}]',1004,'1','2025-07-30 14:09:22','2026-07-14 18:14:17'),(8,1,2,'Premium Grey Lounge Chair',2,2,1,'A cozy lounge chair with soft fabric upholstery and a sleek modern design.','simple',NULL,'','[\"Hf2.jpg\"]','[{\"id\":2,\"price\":\"130\"}]','[{\"id\":1,\"price\":\"90\"}]','[{\"name\":\"default\",\"regular_price\":\"188\",\"sales_price\":\"162\",\"images\":[\"img_6889da4157d3a1753864769.jpg\"]}]',944,'1','2025-07-30 14:09:29','2026-07-14 18:14:17'),(9,1,2,'Elegant Multi-Drawer Storage Cabinet',2,2,NULL,'A sleek cabinet designed with multiple drawers and doors to keep your essentials neatly stored.','simple',NULL,'','[\"hf3.avif\"]','[{\"id\":2,\"price\":\"130\"}]','[{\"id\":1,\"price\":\"90\"}]','[{\"name\":\"default\",\"regular_price\":\"188\",\"sales_price\":\"162\",\"images\":[]}]',1001,'1','2025-07-30 14:10:03','2026-07-14 18:14:17'),(10,1,2,'Modular Dual-Storage Desk',2,2,NULL,'A minimalist, charcoal-grey workstation featuring a contrast-edge tabletop supported by a sto